import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BQq6mqvm.js";const c=JSON.parse('{"title":"登录","description":"","frontmatter":{},"headers":[],"relativePath":"usage/login.md","filePath":"usage/login.md","lastUpdated":1790385461000}'),d={name:"usage/login.md"};function n(l,t,s,i,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h1><h2 id="打开页面" tabindex="-1">打开页面 <a class="header-anchor" href="#打开页面" aria-label="Permalink to &quot;打开页面&quot;">​</a></h2><p>在浏览器里输入管理员给你的网址，例如 <code>http://192.168.1.100</code>。建议把这个地址加入收藏夹。</p><h2 id="输入账号" tabindex="-1">输入账号 <a class="header-anchor" href="#输入账号" aria-label="Permalink to &quot;输入账号&quot;">​</a></h2><p>登录需要两项：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>工号</strong></td><td>你的工号，由管理员创建时设定，登录后不能修改</td></tr><tr><td><strong>密码</strong></td><td>初始密码由管理员告知，建议首次登录后立即修改</td></tr></tbody></table><p>姓名只用于在界面上显示，<strong>不用来登录</strong>。</p><p>填好后点击「登录」。</p><h2 id="登录后的界面" tabindex="-1">登录后的界面 <a class="header-anchor" href="#登录后的界面" aria-label="Permalink to &quot;登录后的界面&quot;">​</a></h2><p>登录成功后进入<strong>我的文件</strong>页面，左侧是人员目录，右侧是文件列表。</p><p>顶部右侧显示你的姓名和工号，点击可以：</p><ul><li><strong>个人设置</strong> —— 查看自己的信息、修改密码</li><li><strong>退出登录</strong> —— 退出当前账号</li></ul><p>左侧菜单包含：</p><table tabindex="0"><thead><tr><th>菜单</th><th>说明</th></tr></thead><tbody><tr><td>我的文件</td><td>只看自己上传的文件（这里才能上传、修改和删除）</td></tr><tr><td>分享管理</td><td>查看和管理分享链接</td></tr><tr><td>全部文件（可展开）</td><td>展开后点某个人的名字，浏览他的文件（只能浏览和下载，不能改）</td></tr><tr><td>管理（管理员可见）</td><td>工作台、用户、文件与回收站、系统管理</td></tr></tbody></table><h2 id="换成自己的密码" tabindex="-1">换成自己的密码 <a class="header-anchor" href="#换成自己的密码" aria-label="Permalink to &quot;换成自己的密码&quot;">​</a></h2><p>点击右上角姓名 → <strong>个人设置</strong> → <strong>修改密码</strong>：</p><ol><li>输入当前密码</li><li>输入新密码（至少 6 位）</li><li>再输入一次确认</li><li>点击「保存并重新登录」</li></ol><p>修改成功后<strong>所有已登录的设备都会退出</strong>，需要用新密码重新登录。这是为了防止旧密码泄露后被继续使用。</p><h2 id="登录不上怎么办" tabindex="-1">登录不上怎么办 <a class="header-anchor" href="#登录不上怎么办" aria-label="Permalink to &quot;登录不上怎么办&quot;">​</a></h2><p><strong>提示「工号或密码错误」</strong> 检查工号有没有输错（前后不要有空格）、密码大小写是否正确。连续输错多次会暂时被限制，等几分钟再试。</p><p><strong>提示「账号已被停用」</strong> 你的账号被管理员停用了，请联系管理员。</p><p><strong>提示「无法在此网络下使用，请更换网络再试！」</strong> 这说明请求没有到达服务器，通常是<strong>不在公司网络</strong>。连接公司网络或 VPN 后再试。详见<a href="./../guide/faq">常见问题</a>。</p><p><strong>什么都没有发生</strong> 确认网址是否正确、服务器是否在运行。可以联系管理员。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./files">浏览与下载文件</a></li><li><a href="./upload">上传文件</a></li></ul>',25)])])}const u=a(d,[["render",n]]);export{c as __pageData,u as default};
